  "VRInvalidClass": "Neplatný kód. Zkontrolujte prosím a zkuste to znovu.",
  "The Android OS version of Chrome currently is broken": "Verze prohlížeče Chrome pro operační systém Android v současné době omezuje uživatele v načítání souborů VEXcode VR. Do vyřešení tohoto problému používejte prosím verzi Firefoxu pro Android.",
  "Welcome to VEXcode VR": "Vítejte ve VEXcode VR!",
