  "Smart Field Controller Detected": "VEXcode V5 nepodporuje programování ani aktualizace firmwaru pro Smart Field Controllery. Více informací o jejich používání najdete pod tlačítkem „Další informace“ níže.",
  "GO bootloader update needed offline error": "Pro aktualizaci zařízení VEX GO Brain je vyžadováno připojení k internetu. Pro pokračování v aktualizaci firmwaru se prosím připojte k internetu a poté se znovu připojte k zařízení VEX GO Brain.",
  "unable to reach skills score server": "VEXcode VR se nemůže připojit k serveru a odeslat skóre Virtual Skills. Odesílání skóre teď není k dispozici. Jak povolit potřebné servery, najdete v Knihovně VEX.",
  "Canceled open": "Proces otevírání byl zrušen.",
  "No write access open": "Nedávno otevřený projekt nelze automaticky uložit, protože se nachází v umístění, které ukládání neumožňuje. Uložte projekt do nového umístění, kde lze ukládat soubory, abyste povolili automatické ukládání.",
  "Unhandled open error": "Došlo k neočekávané chybě. Projekt se nepodařilo otevřít. Odešlete prosím zpětnou vazbu a ujistěte se, že je ve formuláři zpětné vazby zaškrtnuto políčko „Zahrnout diagnostická data a data o využití“.",
  "Canceled save": "Proces ukládání byl zrušen.",
