  "No edit files permission 2": "Tento problém můžete vyřešit otevřením nastavení prohlížeče a povolením přístupu k souborům (např. „Úprava souborů“ nebo „Přístup k místním souborům“). Pokud tato nastavení nemůžete najít, budete se muset obrátit na své IT administrátory.",
