  "Text projects are currently unavailable on tablet and mobile devices. Please visit this site on a Windows, MacOS, or ChromeOS device to create and edit text projects.": "Textové projekty zatím nejsou dostupné na tabletech a mobilech. Pro tvorbu a úpravu textových projektů otevřete tuto stránku na zařízení s Windows, MacOS nebo ChromeOS.",
