  "VR Robot:   Original virtual VEX robot with a black and orange chassis and includes:   Brain with internal: Timer  Gyro Sensor  Location Sensor  Drivetrain  Electromagnet  Pen with four colors  Two Bumpers: Right and Left  Two Eye    Sensors: Front and Down  Distance Sensor": "VR Robot:   Původní virtuální robot VEX s černooranžovým podvozkem, obsahuje:   Brain s vestavěným: Časovač  Gyroskop  Senzor polohy  Podvozek  Elektromagnet  Pero se čtyřmi barvami  Dva nárazníky: pravý a levý  Dva    oční senzory: přední a spodní  Senzor vzdálenosti",
  "VRC Crunch:  Competition robot with a chrome metal chassis and includes:  Brain with internal:  Timer  Gyro Sensor  Location Sensor  Drivetrain  Lift Motor  Intake Motor  Front Eye Sensor  Distance Sensor": "VRC Crunch:  Soutěžní robot s chromovaným kovovým podvozkem, obsahuje:  Brain s vestavěným:  Časovač  Gyroskop  Senzor polohy  Podvozek  Motor zdvihu  Motor sběrače  Přední oční senzor  Senzor vzdálenosti",
  "A project runtime error has occurred. Please check the Print Console in the Monitor Console for more details.": "Za běhu projektu nastala chyba. Podrobnosti najdete v konzoli výpisu v okně Monitor.",
  "A project runtime error has occurred. Please check the Error Panel for more details.": "Za běhu projektu nastala chyba. Podrobnosti najdete v panelu chyb.",
  "Pasting in VEXcode VR Python": "Vkládání ve VEXcode VR Python",
  "Paste action is unavailable via the Edit menu and Context menu, but you can still use": "Vložení není dostupné v nabídce Úpravy ani v místní nabídce, ale stále můžete použít",
  "for paste": "pro vložení",
  "Your project has been stopped due to a loop without a wait statement. Please add at least a 1-millisecond wait to each loop in your project to resolve this issue. Example code to add to each loop: wait(1, MSEC)": "Projekt byl zastaven kvůli smyčce bez čekání. Přidejte do každé smyčky v projektu čekání alespoň 1 milisekundu. Příklad kódu do každé smyčky: wait(1, MSEC)",
