  "Your VEX AIR firmware is out of date and needs to be updated. Do you want to update now?": "Firmware VEX AIR je zastaralý a je potřeba ho aktualizovat. Chcete ho aktualizovat teď?",
  "Your VEX AIM's firmware is out of date and needs to be updated over a USB connection.": "Firmware VEX AIM je zastaralý a je potřeba ho aktualizovat přes USB.",
  "Your VEX AIM's firmware is out of date and needs to be updated using VEXcode AIM on macOS or Windows over a USB connection.": "Firmware VEX AIM je zastaralý a je potřeba ho aktualizovat pomocí VEXcode AIM v macOS nebo Windows přes USB.",
  "Your VEX V5 Brain's firmware is out of date and needs to be updated using VEXcode V5 on macOS, Windows, or Chromebook over a USB connection. Alternatively, the V5 Brain's firmware can also be updated using the V5 Firmware Utility on macOS or Windows.": "Firmware VEX V5 Brainu je zastaralý a je potřeba ho aktualizovat pomocí VEXcode V5 v macOS, Windows nebo na Chromebooku přes USB. Firmware V5 Brainu lze aktualizovat také nástrojem V5 Firmware Utility v macOS nebo Windows.",
  "Your VEX EXP Brain's firmware is out of date and needs to be updated using VEXcode EXP on macOS or Windows over a USB connection.": "Firmware VEX EXP Brainu je zastaralý a je potřeba ho aktualizovat pomocí VEXcode EXP v macOS nebo Windows přes USB.",
  "Your VEX EXP Brain's firmware and VEX EXP Controller's firmware are out of date and needs to be updated using VEXcode EXP on macOS or Windows over a USB connection.": "Firmware VEX EXP Brainu a VEX EXP ovladače je zastaralý a je potřeba ho aktualizovat pomocí VEXcode EXP v macOS nebo Windows přes USB.",
  "Your VEX EXP Controllers's firmware is out of date and needs to be updated using VEXcode EXP on macOS or Windows over a USB connection.": "Firmware ovladače VEX EXP je zastaralý a je potřeba ho aktualizovat pomocí VEXcode EXP v macOS nebo Windows přes USB.",
  "Your VEX EXP Controllers's firmware is out of date and needs to be updated using VEXcode EXP in the web browser over a USB connection.": "Firmware ovladače VEX EXP je zastaralý a je potřeba ho aktualizovat pomocí VEXcode EXP ve webovém prohlížeči přes USB.",
  "Your VEX IQ Brain's firmware is out of date and needs to be updated using VEXcode IQ on macOS, Windows, or Chromebook over a USB connection.": "Firmware VEX IQ Brainu je zastaralý a je potřeba ho aktualizovat pomocí VEXcode IQ v macOS, Windows nebo na Chromebooku přes USB.",
  "Your VEX IQ Brain's firmware and VEX IQ Controller's firmware are out of date and needs to be updated using VEXcode IQ on macOS, Windows, or Chromebook over a USB connection.": "Firmware VEX IQ Brainu a VEX IQ ovladače je zastaralý a je potřeba ho aktualizovat pomocí VEXcode IQ v macOS, Windows nebo na Chromebooku přes USB.",
  "Your VEX IQ Controllers's firmware is out of date and needs to be updated using VEXcode IQ on macOS, Windows, or Chromebook over a USB connection.": "Firmware ovladače VEX IQ je zastaralý a je potřeba ho aktualizovat pomocí VEXcode IQ v macOS, Windows nebo na Chromebooku přes USB.",
  "Your VEX IQ Controllers's firmware is out of date and needs to be updated using VEXcode IQ in the web browser over a USB connection.": "Firmware ovladače VEX IQ je zastaralý a je potřeba ho aktualizovat pomocí VEXcode IQ ve webovém prohlížeči přes USB.",
