  "The Python VM has been reset due to unresponsiveness - please wait a moment and try again. If the issue continues, check your code and ensure there is at least 5 milliseconds of delay in every loop to avoid locking the Python VM inside of the web browser.": "Python VM byl restartován, protože přestal reagovat – chvíli počkejte a zkuste to znovu. Pokud problém trvá, zkontrolujte kód a ujistěte se, že v každé smyčce je čekání aspoň 5 milisekund, aby se Python VM ve webovém prohlížeči nezasekl.",
  "This project has Blocks that are not available on this playground. Press 'Continue' to continue and disable these blocks, or Press 'Cancel' to return to your project": "Tento projekt obsahuje bloky, které na tomto hřišti nejsou dostupné. Klikněte na „Pokračovat“ a tyto bloky se vypnou, nebo na „Zrušit“ a vraťte se k projektu.",
