  "For M1 Macs/MacBooks, ensure that browser Hardware Acceleration is turned on and reload the page.": "U počítačů Mac/MacBook s procesorem M1 se ujistěte, že je v prohlížeči zapnutá hardwarová akcelerace, a znovu načtěte stránku.",
