  "Warning: You may experience performance issues while using VEXcode VR Playgrounds due to Hardware Acceleration being disabled on this computer. Use the 'More Information' link to learn about how to potentially resolve this issue.": "Upozornění: Při používání hřišť VEXcode VR můžete narazit na problémy s výkonem, protože hardwarová akcelerace je v tomto počítači vypnutá. Jak to případně vyřešit, zjistíte přes odkaz „Další informace“.",
