  "C++ Disabled": "C++ vypnuto",
  "Purchase VR": "Zakoupit VR",
  "Manage Licenses": "Správa licencí",
  "Your current VEXcode VR class code is linked to an expired license. To continue accessing advanced features, please renew your VEXcode VR License.": "Váš aktuální kód kurzu VEXcode VR je propojen s vypršenou licencí. Chcete-li mít i nadále přístup k pokročilým funkcím, obnovte si prosím licenci VEXcode VR.",
  "Invalid code. Please check and try again.": "Neplatný kód. Zkontrolujte prosím a zkuste to znovu.",
  "The Android OS version of Chrome currently limits users from loading VEXcode VR files. Please use the Android version of Firefox as a work around until this issue is resolved.": "Verze prohlížeče Chrome pro operační systém Android v současné době omezuje uživatele v načítání souborů VEXcode VR. Do vyřešení tohoto problému používejte prosím verzi Firefoxu pro Android.",
  "In VEXcode VR, a virtual robot can be coded to do many things!": "Ve VEXcode VR lze virtuálního robota naprogramovat tak, aby dělal spoustu věcí!",
  "Learn about key features of coding with blocks in VEXcode VR to get started.": "Seznamte se s hlavními funkcemi programování bloky ve VEXcode VR.",
  "Click 'Next' or use the arrow keys to navigate through the tour.": "Klikněte na tlačítko „Další“ nebo použijte klávesy se šipkami k procházení prohlídky.",
  "Discover the Toolbox": "Seznamte se s panelem bloků",
  "Use blocks to build projects that control the VR robot.": "Používejte bloky k sestavení projektů, které ovládají VR robota.",
  "The Toolbox lists every behavior available to use with the VR robot.": "Panel bloků obsahuje všechno, co VR robot umí.",
  "The ‘When started’ block": "Blok „když začne program“",
  "Projects begin with a ‘When started’ block.": "Projekty začínají blokem „když začne program“.",
  "Drag blocks from the Toolbox and attach them to the ‘When started’ block to build a project.": "Přetahujte bloky z panelu bloků a připojte je pod blok „když začne program“.",
  "Start a project": "Spusťte projekt",
  "Ready to try a project? Select the ‘Start’ button in the Toolbar.": "Chcete projekt vyzkoušet? Klikněte na tlačítko „Start“ na horní liště.",
  "The Playground window will open, and the VR robot will move!": "Otevře se okno hřiště a VR robot se pohne!",
  "VR Playgrounds": "VR hřiště",
  "VR robots run in environments called Playgrounds.": "VR roboti jezdí v prostředích, kterým se říká hřiště.",
  "Click the ‘Select Playground’ button to choose a playground and get coding!": "Klikněte na tlačítko „Vybrat hřiště“, vyberte si hřiště a začněte programovat!",
  "Save a project": "Uložit projekt",
  "To save a project, select ‘Save to Your Device’ inside the File Menu.": "Chcete-li projekt uložit, vyberte v nabídce Soubor možnost „Uložit do zařízení“.",
  "To save a project, select ‘Save’ inside the File Menu.": "Chcete-li projekt uložit, vyberte v nabídce Soubor možnost „Uložit“.",
  "Get help with any block": "Nápověda ke každému bloku",
  "Learn more about any block in the Toolbox!": "Zjistěte víc o každém bloku v panelu bloků!",
  "Select the Help icon to open the Help feature, then select a block to learn how it works.": "Klikněte na ikonu Nápověda a pak na blok, abyste zjistili, jak funguje.",
  "Learn by example": "Učte se na příkladech",
  "Example projects show how to use different blocks to control the VR robot.": "Příklady projektů ukazují, jak používat různé bloky k ovládání VR robota.",
  "Select 'Open Examples' inside the File Menu to view and select projects to try.": "V nabídce Soubor vyberte možnost „Otevřít příklady“ pro zobrazení a výběr projektů, které chcete vyzkoušet.",
  "Try out a tutorial": "Vyzkoušejte návod",
  "Tutorials explain different coding concepts and VR features.": "Návody vysvětlují různé koncepty kódování a funkce VR.",
  "Select the ‘Tutorials’ button to choose and watch a tutorial.": "Klikněte na tlačítko „Návody“ a vyberte si návod.",
  "Looking for more?": "Chcete víc?",
  "Select the 'Learn' icon to see fun activities and learn more about coding a VR robot.": "Klikněte na ikonu „Učit se“ a najděte zábavné aktivity o programování VR robota.",
  "Translate VEXcode VR": "Přeložit VEXcode VR",
  "Use the Globe icon to view language options in VEXcode VR, and select your desired language.": "Ikonou zeměkoule zobrazíte jazyky VEXcode VR a vyberete požadovaný jazyk.",
  "How to Monitor": "Jak sledovat hodnoty",
  "New in VEXcode VR!": "Novinka ve VEXcode VR!",
  "Meet the Monitor! Drag and drop blocks onto the Monitor icon to track sensors, variables, and lists.": "Seznamte se s Monitorem! Přetáhněte bloky na ikonu Monitoru a sledujte senzory, proměnné a seznamy.",
  "Share your thoughts": "Napište nám svůj názor",
  "Congratulations, the tour is complete!": "Gratulujeme, prohlídka je hotová!",
  "Have fun coding!": "Užijte si programování!",
  "Help us make VEXcode VR even better by using the 'Feedback' button.": "Pomozte nám ještě vylepšit VEXcode VR pomocí tlačítka „Zpětná vazba“.",
  "Welcome to VEXcode CTE!": "Vítejte ve VEXcode CTE!",
  "Learn how to connect and use the 6-Axis Arm with VEXcode.": "Naučte se, jak připojit a používat 6osé rameno s VEXcode.",
  "Learn to connect the arm": "Jak připojit rameno",
  "Plug the arm into the computer, Click 'Connect Arm,' and follow the connection prompts.": "Zapojte rameno do počítače, klikněte na „Připojit rameno“ a postupujte podle pokynů k připojení.",
  "Plug the arm into the computer to connect the arm to VEXcode. Know the arm is connected when the icon turns green.": "Zapojte rameno do počítače, abyste ho připojili k VEXcode. Rameno je připojeno, když se ikona rozsvítí zeleně.",
  "Meet the Teach Pendant!": "Seznamte se s ovládacím panelem (Teach Pendant)!",
  "Have the arm directly connected? Use the Teach Pendant to manually move the arm by increments or to a coordinate position.": "Je rameno přímo připojeno? Pomocí ovládacího panelu můžete rameno ručně posouvat po krocích nebo do souřadnicové polohy.",
  "Coding the arm": "Programování ramene",
  "Use the arm blocks to build projects that control the arm.": "Použijte bloky ramene k vytvoření projektů, které ovládají rameno.",
  "The toolbox lists every behavior available to use with the arm.": "Panel bloků obsahuje všechno, co rameno umí.",
  "Run, Step, and Stop!": "Spustit, Krok a Zastavit!",
  "Click 'Run' to start a project and get the arm moving. Click 'Step' to watch block by block.": "Kliknutím na tlačítko „Spustit“ spusťte projekt a uveďte rameno do pohybu. Kliknutím na tlačítko „Krokovat“ můžete sledovat postup blok po bloku.",
  "Just note, when a project is running, the teach pendant cannot be used!": "Pozor: když běží projekt, ovládací panel nelze použít!",
  "Using the Monitor": "Použití Monitoru",
  "Track the arm's position while running projects by viewing the monitor tab.": "Během projektu sledujte polohu ramene na kartě Monitor.",
  "To learn more about the monitor, click the 'How to Monitor' button": "Chcete-li se o Monitoru dozvědět více, klikněte na tlačítko „Jak sledovat hodnoty“",
