  "Saving help": "Pomoc s ukládáním",
  "VEXcode V5 does not support coding or firmware updates for Smart Field Controllers. For more details on using Smart Field Controllers, select the ‘More Information’ button below.": "VEXcode V5 nepodporuje programování ani aktualizace firmwaru pro Smart Field Controllery. Více informací o jejich používání najdete pod tlačítkem „Další informace“ níže.",
  "Internet connection required to update your VEX GO Brain. Please connect to the internet, then reconnect to your VEX GO Brain to proceed with the firmware update.": "Pro aktualizaci zařízení VEX GO Brain je vyžadováno připojení k internetu. Pro pokračování v aktualizaci firmwaru se prosím připojte k internetu a poté se znovu připojte k zařízení VEX GO Brain.",
  "VEXcode VR is unable to connect to the server to submit Virtual Skills scores. Score submissions are currently unavailable. Please refer to the VEX Library for details on whitelisting the required servers.": "VEXcode VR se nemůže připojit k serveru a odeslat skóre Virtual Skills. Odesílání skóre teď není k dispozici. Jak povolit potřebné servery, najdete v Knihovně VEX.",
  "The opening process has been canceled.": "Proces otevírání byl zrušen.",
  "Cannot auto-save the recently opened project because it is in a location that does not allow saving. Please save the project to a new location where files can be saved to enable auto-save.": "Nedávno otevřený projekt nelze automaticky uložit, protože se nachází v umístění, které ukládání neumožňuje. Uložte projekt do nového umístění, kde lze ukládat soubory, abyste povolili automatické ukládání.",
  "An unexpected error occurred. The project could not be opened. Please submit feedback and ensure that 'Include diagnostics and usage data' is checked in the feedback form.": "Došlo k neočekávané chybě. Projekt se nepodařilo otevřít. Odešlete prosím zpětnou vazbu a ujistěte se, že je ve formuláři zpětné vazby zaškrtnuto políčko „Zahrnout diagnostická data a data o využití“.",
  "The saving process has been canceled.": "Proces ukládání byl zrušen.",
  "Cannot save the project because the selected location does not allow saving. Please choose a location where files can be saved.": "Projekt nelze uložit, protože vybrané umístění uložení neumožňuje. Vyberte prosím umístění, kam lze soubory uložit.",
  "An unexpected error occurred. The project could not be saved. Please submit feedback and ensure that 'Include diagnostics and usage data' is checked in the feedback form.": "Došlo k neočekávané chybě. Projekt se nepodařilo uložit. Odešlete prosím zpětnou vazbu a ujistěte se, že je ve formuláři zpětné vazby zaškrtnuto políčko „Zahrnout diagnostická data a data o využití“.",
  "Save to New Location": "Uložit do nového umístění",
  "Help submitting feedback >": "Pomoc s odesíláním zpětné vazby >",
  "Browser Error Message": "Chybová zpráva prohlížeče",
  "Your browser settings are preventing access to files, which is necessary for opening or saving projects.": "Nastavení vašeho prohlížeče brání přístupu k souborům, což je nezbytné pro otevírání nebo ukládání projektů.",
  "You can fix this issue by opening your browser settings and enabling the setting for file access (e.g., “File Editing” or “Local File Access”). If unable to find these setting, you will need to check with your IT Administrators.": "Tento problém můžete vyřešit otevřením nastavení prohlížeče a povolením přístupu k souborům (např. „Úprava souborů“ nebo „Přístup k místním souborům“). Pokud tato nastavení nemůžete najít, budete se muset obrátit na své IT administrátory.",
  "Invalid file extension. Please save the file without using periods to continue.": "Neplatná přípona souboru. Pro pokračování prosím uložte soubor bez teček.",
  "Driver Installation Required": "Vyžadována instalace driverů",
  "If you’ve already installed the driver package, you can safely continue and connect to your controller.": "Pokud už máte balíček driverů nainstalovaný, můžete bez obav pokračovat a připojit ovladač.",
  "Download Drivers": "Stáhnout drivery",
  "Note: Text will not be sent to the console until a new line is started": "Poznámka: Text nebude odeslán do konzole, dokud nebude zahájen nový řádek.",
  "Connect Console Serial Port": "Připojit sériový port konzole",
  "Console Serial Port is not connected - please connect to the Console Serial Port to enable the Console": "Sériový port konzole není připojen – pro aktivaci konzole se prosím připojte k sériovému portu konzole.",
  "AIM Robot is not connected - please connect an AIM Robot to enable the Console": "Robot AIM není připojen – pro aktivaci konzole prosím připojte robota AIM.",
  "AIM Robot is not connected - please connect an AIM Robot to enable the AI Vision Dashboard": "Robot AIM není připojen – pro aktivaci řídicího panelu AI Vision připojte robota AIM.",
  "Please connect to the Console Serial Port to enable the Console.": "Pro aktivaci konzole se prosím připojte k sériovému portu konzole.",
  "Unable to load the project. Switch blocks are not supported on this device. Please use VEXcode on Windows, Chrome OS, or macOS to access this project.": "Projekt nelze načíst. Bloky switch nejsou na tomto zařízení podporovány. Pro otevření projektu použijte VEXcode ve Windows, Chrome OS nebo macOS.",
